# Generated by tools/release from the artifact manifest. Do not edit by hand.
# Tap: juliankang4/homebrew-tap
class Owngit < Formula
  desc "Private Git storage and browser dashboard on your own computer"
  homepage "https://github.com/juliankang4/owngit"
  license "MIT"

  depends_on "git"

  on_macos do
    on_arm do
      url "https://github.com/juliankang4/owngit/releases/download/v1.1.4/owngit_1.1.4_darwin_arm64.tar.gz"
      sha256 "5fda5d4a121c4b38f1b846ce9067c921d365ba575270cb941af8f523a180b86f"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/juliankang4/owngit/releases/download/v1.1.4/owngit_1.1.4_linux_amd64.tar.gz"
      sha256 "e3dcaa79bae3fadea5b82c2b2d558f229edfba10577cd7fabfd92036c5b17146"
    end
    on_arm do
      url "https://github.com/juliankang4/owngit/releases/download/v1.1.4/owngit_1.1.4_linux_arm64.tar.gz"
      sha256 "fec883890e8035c97e6a7f432b0dcefc0624a6e995e3c68008bb78498b75b0c2"
    end
  end

  def install
    bin.install "owngit"
    # OwnGit.app, the menu bar icon, next to the bin folder of the program;
    # "owngit service install" opens it from there.
    prefix.install "OwnGit.app" if OS.mac?
    prefix.install "LICENSE"
    prefix.install "THIRD_PARTY_NOTICES"
  end

  # launchd would create the service's output file readable by everyone, so
  # it is created first, for the owner only, as owngit creates its log.
  post_install_steps do
    mkdir_p "log", base: :var
    touch "log/owngit.stderr.log", base: :var
    set_permissions "log/owngit.stderr.log", "0600", base: :var
  end

  # The server log, where the first start writes the setup file path, is
  # var/log/owngit.log, which owngit keeps below 10 MiB with one older file
  # beside it. The service's own output holds only what the log cannot,
  # such as a crash report.
  service do
    run [opt_bin/"owngit", "serve", "-no-open", "--log-file", var/"log/owngit.log", "--service"]
    keep_alive true
    process_type :interactive
    log_path var/"log/owngit.stderr.log"
    error_log_path var/"log/owngit.stderr.log"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/owngit version")
  end
end
